      handler(...args);
      this.off(event, onceWrapper);
    };
    return this.on(event, onceWrapper);
  }

  emit(event, ...args) {
    if (!this.events.has(event)) return false;
    const handlers = this.events.get(event);
    handlers.forEach(handler => handler(...args));
